+		"21.04": {"2022-01-30", ""},
+	},
+	Debian: {
+		"9":  {"2022-06-30", ""},
+		"10": {"2024-06-30", ""},
+		"8":  {"2020-06-30", "2020-06-30"},
+	},
+	Alpine: {
+		"3.10": {"2021-05-30", ""},
