+		"14.04": {"2019-04-30", "2024-04-30"},
+		"14.10": {"2015-07-30", "2015-07-30"},
+		"21.04": {"2022-01-30", ""},
+	},
+	Debian: {
+		"9":  {"2022-06-30", ""},
+		"10": {"2024-06-30", ""},
+		"8":  {"2020-06-30", "2020-06-30"},
+	},
+	Alpine: {
+		"3.10": {"2021-05-30", ""},
+		"3.11": {"2021-11-30", ""},
+		"3.12": {"2022-05-30", ""},
